              <div class="eap-value">{{ pExt("first-name") || "—" }}</div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Middle Name</div>
              <div class="eap-value">{{ pExt("middle-name") || "—" }}</div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Surname</div>
              <div class="eap-value">{{ pExt("surname") || "—" }}</div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Date of Birth</div>
              <div class="eap-value">
                {{ fmtDate(pExt("birthdate", "valueDate")) || "—" }}
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Sex</div>
              <div class="eap-value">
                {{ pExtCoding("person-gender") || "—" }}
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Place of Birth</div>
              <div class="eap-value">{{ pExt("birth-place") || "—" }}</div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Marital Status</div>
              <div class="eap-value">
                {{ pExtCoding("marital-status") || "—" }}
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Disability</div>
              <div class="eap-value">
                {{ pExtCoding("ihris-practitioner-disability") || "—" }}
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Nationality</div>
              <div class="eap-value">
                {{ pExtCoding("ihris-practitioner-nationality") || "—" }}
              </div>
