              <div class="eap-value">{{ pExt("passport-number") || "—" }}</div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Passport Issue Date</div>
              <div class="eap-value">
                {{ fmtDate(pExt("passport-issue-date", "valueDate")) || "—" }}
              </div>
            </v-col>
            <v-col cols="12" sm="6" md="4">
              <div class="eap-label">Passport Expiry Date</div>
              <div class="eap-value">
                {{ fmtDate(pExt("passport-expiry-date", "valueDate")) || "—" }}
              </div>
