                  </div>
                </v-col>
                <v-col cols="12" sm="6">
                  <div class="eap-label">Date of Leaving</div>
                  <div class="eap-value">
                    {{
                      fmtDate(pSubOf(sa, "date-of-leaving", "valueDate")) || "—"
