                </v-col>
                <v-col cols="12" sm="6">
                  <div class="eap-label">Grade / Class</div>
                  <div class="eap-value">{{ pSubOf(ep, "grade") || "—" }}</div>
                </v-col>
                <v-col cols="12" sm="6">
                  <div class="eap-label">Start Year</div>
                  <div class="eap-value">
                    {{ fmtDate(pSubOf(ep, "start-year", "valueDate")) || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6">
                  <div class="eap-label">End Year</div>
                  <div class="eap-value">
                    {{ fmtDate(pSubOf(ep, "end-year", "valueDate")) || "—" }}
                  </div>
