                  <div class="eap-label">Subject Name</div>
                  <div class="eap-value font-weight-bold">
                    {{ pSubOf(sp, "name") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="4">
                  <div class="eap-label">Grade</div>
                  <div class="eap-value">{{ pSubOf(sp, "grade") || "—" }}</div>
                </v-col>
              </v-row>
            </div>
          </div>
          <v-divider
            v-if="
              (pAllExts('schools-attended').length ||
                pAllExts('examination-passed').length ||
                pAllExts('subject-passed').length) &&
                pAllExts('post-secondary-education').length
