                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Date of Entry</div>
                  <div class="eap-value">
                    {{
                      fmtDate(pSubOf(edu, "date-of-entry", "valueDate")) || "—"
                    }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Date of Leaving</div>
                  <div class="eap-value">
                    {{
                      fmtDate(pSubOf(edu, "date-of-leaving", "valueDate")) ||
                        "—"
                    }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Qualification</div>
                  <div class="eap-value">
                    {{ pSubOf(edu, "qualification-name") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Date Obtained</div>
                  <div class="eap-value">
                    {{
                      fmtDate(pSubOf(edu, "qualification-date", "valueDate")) ||
                        "—"
                    }}
                  </div>
                </v-col>
                <v-col
                  cols="12"
                  v-if="pAllSubsOf(edu, 'distinctions-gained').length"
                >
                  <div class="eap-label">Distinctions Gained</div>
                  <div class="d-flex flex-wrap gap-1 mt-1">
                    <v-chip
                      v-for="(dg, dgi) in pAllSubsOf(
                        edu,
                        'distinctions-gained',
                      )"
                      :key="'dg-' + dgi"
                      small
                      color="blue lighten-5"
                      text-color="blue darken-2"
                      class="mr-1 mb-1"
                      >{{ dg }}</v-chip
                    >
                  </div>
                </v-col>
              </v-row>
            </div>
