                  </div>
                </v-col>
                <v-col cols="12" v-if="pSubOf(aq, 'notes')">
                  <div class="eap-label">Notes</div>
                  <div class="eap-value">{{ pSubOf(aq, "notes") }}</div>
                </v-col>
              </v-row>
            </div>
