              v-for="(cr, i) in pAllExts('council-registration')"
              :key="'cr-' + i"
            >
              <v-divider v-if="i > 0" class="my-3"></v-divider>
              <div class="caption grey--text mb-1"># {{ i + 1 }}</div>
              <v-row dense>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Registration Council</div>
                  <div class="eap-value font-weight-bold">
                    {{ pSubOfCoding(cr, "council") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Registration Number</div>
                  <div class="eap-value">
                    {{ pSubOf(cr, "registration-number") || "—" }}
                  </div>
