                  <div class="eap-label">License Status</div>
                  <v-chip small class="mt-1">
                    {{ pSubOfCoding(cr, "license-status") || "—" }}
                  </v-chip>
                </v-col>
              </v-row>
            </div>
          </div>
          <div v-else class="text-center grey--text body-2 py-8">
            No council registration information provided.
          </div>
