                  <div class="eap-label">Salary</div>
                  <div class="eap-value">
                    {{ pSubOf(eh, "salary", "valueDecimal") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Notice Period</div>
                  <div class="eap-value">
                    {{ pSubOf(eh, "notice-period") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" v-if="pSubOf(eh, 'capacity')">
                  <div class="eap-label">Capacity</div>
                  <div class="eap-value">{{ pSubOf(eh, "capacity") }}</div>
                </v-col>
                <v-col cols="12" v-if="pSubOf(eh, 'duties-nature')">
                  <div class="eap-label">Nature of Duties</div>
                  <div class="eap-value">{{ pSubOf(eh, "duties-nature") }}</div>
                </v-col>
                <v-col cols="12" v-if="pSubOf(eh, 'reason-for-leaving')">
                  <div class="eap-label">Reason for Leaving</div>
                  <div class="eap-value">
                    {{ pSubOf(eh, "reason-for-leaving") }}
