                </v-col>
              </v-row>
            </div>
          </div>
          <div v-else class="text-center grey--text body-2 py-8">No employment history provided.</div>
        </v-card-text>
      </v-tab-item>

      <!-- TAB 3: Family -->
      <v-tab-item>
