              </v-col>
              <v-col cols="12" sm="6" md="4">
                <div class="eap-label">Nationality</div>
                <div class="eap-value">
                  {{
                    pNestedSubCoding("spouse-particulars", "nationality") || "—"
                  }}
                </div>
              </v-col>
            </v-row>
          </div>
          <div
            v-if="
              !pNestedExt('father-particulars') &&
                !pNestedExt('spouse-particulars')
            "
            class="text-center grey--text body-2 py-8"
          >
            No family information provided.
          </div>
        </v-card-text>
      </v-tab-item>

      <!-- TAB 6: References & Declarations -->
      <v-tab-item>
        <v-card-text>
          <div v-if="pAllExts('personal-reference').length">
            <div class="caption font-weight-bold blue--text text--darken-3 text-uppercase mb-2 mt-1">Personal References</div>
            <div
              v-for="(pr, i) in pAllExts('personal-reference')"
              :key="'pr-' + i"
            >
              <v-divider v-if="i > 0" class="my-3"></v-divider>
              <div class="caption grey--text mb-1"># {{ i + 1 }}</div>
              <v-row dense>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Name</div>
                  <div class="eap-value font-weight-bold">
                    {{ pSubOf(pr, "name") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Occupation</div>
                  <div class="eap-value">
                    {{ pSubOf(pr, "occupation") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Address</div>
                  <div class="eap-value">
                    {{ pSubOf(pr, "address") || "—" }}
                  </div>
                </v-col>
                <v-col cols="12" sm="6" md="4">
                  <div class="eap-label">Period Known</div>
                  <div class="eap-value">{{ pSubOf(pr, "period") || "—" }}</div>
                </v-col>
              </v-row>
            </div>
            <v-divider class="my-4"></v-divider>
          </div>
          <div class="caption font-weight-bold blue--text text--darken-3 text-uppercase mb-2 mt-1">Declarations</div>
          <v-row dense>
            <v-col cols="12" sm="6">
              <div class="eap-label">Convicted of a criminal offense?</div>
              <v-chip
                small
                :color="
                  pExtCoding('convicted-of-criminal-offense') === 'Yes'
                    ? 'red lighten-4'
                    : pExtCoding('convicted-of-criminal-offense') === 'No'
                    ? 'green lighten-4'
                    : 'grey lighten-3'
                "
                :text-color="
                  pExtCoding('convicted-of-criminal-offense') === 'Yes'
                    ? 'red darken-2'
                    : pExtCoding('convicted-of-criminal-offense') === 'No'
                    ? 'green darken-2'
                    : 'grey darken-1'
                "
                class="mt-1"
                >{{
                  pExtCoding("convicted-of-criminal-offense") || "—"
                }}</v-chip
              >
            </v-col>
            <v-col cols="12" sm="6">
              <div class="eap-label">Dismissed from service before?</div>
              <v-chip
                small
                :color="
                  pExtCoding('dismissed-from-service-before') === 'Yes'
                    ? 'red lighten-4'
                    : pExtCoding('dismissed-from-service-before') === 'No'
                    ? 'green lighten-4'
                    : 'grey lighten-3'
                "
                :text-color="
                  pExtCoding('dismissed-from-service-before') === 'Yes'
                    ? 'red darken-2'
                    : pExtCoding('dismissed-from-service-before') === 'No'
                    ? 'green darken-2'
                    : 'grey darken-1'
                "
                class="mt-1"
                >{{
                  pExtCoding("dismissed-from-service-before") || "—"
                }}</v-chip
              >
            </v-col>
          </v-row>
        </v-card-text>
      </v-tab-item>
    </v-tabs-items>
  </div>
</template>

<script>
export default {
  name: "ExternalApplicantProfile",

  props: {
    profile: {
      type: Object,
      required: true,
    },
  },

  data() {
    return {
      profileTab: 0,
    };
  },

  computed: {
    profileFullName() {
      const exts = this.profile.extension || [];
      const get = (s) => exts.find((x) => x.url.endsWith("/" + s))?.valueString;
      return (
        [get("first-name"), get("middle-name"), get("surname")]
          .filter(Boolean)
          .join(" ") || "Applicant"
      );
    },

    profileInitials() {
      return this.profileFullName
        .split(" ")
        .slice(0, 2)
        .map((w) => w[0])
        .join("")
        .toUpperCase();
    },
  },

  methods: {
    pExt(urlSuffix, field = "valueString") {
      const exts = this.profile.extension || [];
      const e = exts.find((x) => x.url.endsWith("/" + urlSuffix));
      return e ? e[field] ?? null : null;
    },

    pExtCoding(urlSuffix) {
      const exts = this.profile.extension || [];
      const e = exts.find((x) => x.url.endsWith("/" + urlSuffix));
      return e?.valueCoding?.display ?? null;
    },

    pNestedExt(urlSuffix) {
      const exts = this.profile.extension || [];
      return exts.find((x) => x.url.endsWith("/" + urlSuffix)) ?? null;
    },

    pNestedSub(urlSuffix, subUrl, field = "valueString") {
      const parent = this.pNestedExt(urlSuffix);
      if (!parent?.extension) return null;
      const child = parent.extension.find((x) => x.url === subUrl);
      return child ? child[field] ?? null : null;
    },

    pNestedSubCoding(urlSuffix, subUrl) {
      const parent = this.pNestedExt(urlSuffix);
      if (!parent?.extension) return null;
      const child = parent.extension.find((x) => x.url === subUrl);
      return child?.valueCoding?.display ?? null;
    },

    pAllExts(urlSuffix) {
      const exts = this.profile.extension || [];
      return exts.filter((x) => x.url.endsWith("/" + urlSuffix));
    },

    pSubOf(extEntry, subUrl, field = "valueString") {
      if (!extEntry?.extension) return null;
      const child = extEntry.extension.find((x) => x.url === subUrl);
      return child ? child[field] ?? null : null;
    },

    pSubOfCoding(extEntry, subUrl) {
      if (!extEntry?.extension) return null;
      const child = extEntry.extension.find((x) => x.url === subUrl);
      if (!child) return null;
      return (
        child.valueCoding?.display ||
        child.valueCoding?.code ||
        child.valueString ||
        null
      );
    },

    pAllSubsOf(extEntry, subUrl, field = "valueString") {
      if (!extEntry?.extension) return [];
      return extEntry.extension
        .filter((x) => x.url === subUrl)
        .map((x) => x[field])
        .filter((v) => v != null && v !== "");
    },

    fmtDate(val) {
      if (!val) return null;
      try {
        const [y, m, d] = val.split("T")[0].split("-");
        if (!y) return val;
        if (!m) return y;
        const months = [
          "Jan",
          "Feb",
          "Mar",
          "Apr",
          "May",
          "Jun",
          "Jul",
          "Aug",
          "Sep",
          "Oct",
          "Nov",
          "Dec",
        ];
        if (!d) return `${months[parseInt(m, 10) - 1]} ${y}`;
        return `${parseInt(d, 10)} ${months[parseInt(m, 10) - 1]} ${y}`;
      } catch {
        return val;
      }
    },
  },
};
</script>

